import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Card,
  CardContent,
  Tabs,
  Tab,
  TextField,
  MenuItem,
  InputAdornment,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  Chip,
  IconButton,
  Tooltip,
  Button,
} from "@mui/material";
import {
  Search as SearchIcon,
  Download as DownloadIcon,
} from "@mui/icons-material";
import { sosAPI, incidentAPI } from "../services/api";
import Loading from "../components/Loading";
import toast from "react-hot-toast";

const statusColors = {
  active: "error",
  acknowledged: "warning",
  resolved: "success",
  cancelled: "default",
  pending: "warning",
  investigating: "info",
  closed: "default",
};

const severityColors = {
  low: "success",
  medium: "info",
  high: "warning",
  critical: "error",
};

const AlertHistory = () => {
  const [tab, setTab] = useState(0);
  const [sosAlerts, setSosAlerts] = useState([]);
  const [incidents, setIncidents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("");

  useEffect(() => {
    fetchData();
  }, [tab, page, rowsPerPage, statusFilter]);

  const fetchData = async () => {
    setLoading(true);
    try {
      if (tab === 0) {
        const params = { page: page + 1, per_page: rowsPerPage };
        if (statusFilter) params.status = statusFilter;
        if (search) params.search = search;
        const response = await sosAPI.getHistory(params);
        setSosAlerts(response.data.alerts || []);
      } else {
        const params = { page: page + 1, per_page: rowsPerPage };
        if (statusFilter) params.status = statusFilter;
        if (search) params.search = search;
        const response = await incidentAPI.getAll(params);
        setIncidents(response.data || []);
      }
    } catch (error) {
      toast.error("Failed to load history");
    } finally {
      setLoading(false);
    }
  };

  const exportToCSV = () => {
    const data = tab === 0 ? sosAlerts : incidents;
    if (data.length === 0) {
      toast.error("No data to export");
      return;
    }

    let csvContent = "";

    if (tab === 0) {
      csvContent = "Type,Message,Location,Status,Date\n";
      data.forEach((alert) => {
        csvContent += `"${alert.alert_type}","${alert.message || ""}","${alert.address || ""}","${alert.status}","${new Date(alert.created_at).toLocaleString()}"\n`;
      });
    } else {
      csvContent = "Incident ID,Type,Description,Location,Severity,Status,Date\n";
      data.forEach((incident) => {
        csvContent += `"${incident.incident_id}","${incident.incident_type}","${incident.description}","${incident.location}","${incident.severity}","${incident.status}","${new Date(incident.created_at).toLocaleString()}"\n`;
      });
    }

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `${tab === 0 ? "sos_alerts" : "incidents"}_history.csv`;
    link.click();
    toast.success("CSV downloaded successfully");
  };

  return (
    <Box>
      <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", mb: 3 }}>
        <Box>
          <Typography variant="h4" fontWeight={700}>
            Alert History
          </Typography>
          <Typography variant="body1" color="text.secondary">
            View all your alerts and incident reports
          </Typography>
        </Box>
        <Button
          variant="outlined"
          startIcon={<DownloadIcon />}
          onClick={exportToCSV}
        >
          Export CSV
        </Button>
      </Box>

      <Card>
        <CardContent>
          <Tabs
            value={tab}
            onChange={(e, v) => {
              setTab(v);
              setPage(0);
              setStatusFilter("");
              setSearch("");
            }}
            sx={{ mb: 3 }}
          >
            <Tab label="SOS Alerts" />
            <Tab label="Incident Reports" />
          </Tabs>

          <Box sx={{ display: "flex", gap: 2, mb: 3, flexWrap: "wrap" }}>
            <TextField
              size="small"
              placeholder="Search..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && fetchData()}
              sx={{ flex: 1, minWidth: 200 }}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon color="action" />
                  </InputAdornment>
                ),
              }}
            />
            <TextField
              size="small"
              select
              label="Status"
              value={statusFilter}
              onChange={(e) => {
                setStatusFilter(e.target.value);
                setPage(0);
              }}
              sx={{ minWidth: 130 }}
            >
              <MenuItem value="">All</MenuItem>
              {tab === 0 ? (
                <>
                  <MenuItem value="active">Active</MenuItem>
                  <MenuItem value="acknowledged">Acknowledged</MenuItem>
                  <MenuItem value="resolved">Resolved</MenuItem>
                  <MenuItem value="cancelled">Cancelled</MenuItem>
                </>
              ) : (
                <>
                  <MenuItem value="pending">Pending</MenuItem>
                  <MenuItem value="investigating">Investigating</MenuItem>
                  <MenuItem value="resolved">Resolved</MenuItem>
                  <MenuItem value="closed">Closed</MenuItem>
                </>
              )}
            </TextField>
          </Box>

          {loading ? (
            <Loading message="Loading history..." />
          ) : tab === 0 ? (
            sosAlerts.length > 0 ? (
              <>
                <TableContainer>
                  <Table>
                    <TableHead>
                      <TableRow>
                        <TableCell>Alert Type</TableCell>
                        <TableCell>Message</TableCell>
                        <TableCell>Location</TableCell>
                        <TableCell>Status</TableCell>
                        <TableCell>Date & Time</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {sosAlerts.map((alert) => (
                        <TableRow key={alert.id} hover>
                          <TableCell>
                            <Chip label={alert.alert_type} size="small" variant="outlined" />
                          </TableCell>
                          <TableCell sx={{ maxWidth: 200 }}>
                            <Typography variant="body2" noWrap>
                              {alert.message || "No message"}
                            </Typography>
                          </TableCell>
                          <TableCell sx={{ maxWidth: 200 }}>
                            <Typography variant="body2" noWrap>
                              {alert.address || "No location"}
                            </Typography>
                          </TableCell>
                          <TableCell>
                            <Chip
                              label={alert.status}
                              size="small"
                              color={statusColors[alert.status]}
                            />
                          </TableCell>
                          <TableCell>
                            {new Date(alert.created_at).toLocaleString()}
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
                <TablePagination
                  component="div"
                  count={sosAlerts.length}
                  page={page}
                  onPageChange={(e, p) => setPage(p)}
                  rowsPerPage={rowsPerPage}
                  onRowsPerPageChange={(e) => {
                    setRowsPerPage(parseInt(e.target.value));
                    setPage(0);
                  }}
                />
              </>
            ) : (
              <Typography textAlign="center" color="text.secondary" sx={{ py: 4 }}>
                No SOS alerts found.
              </Typography>
            )
          ) : incidents.length > 0 ? (
            <>
              <TableContainer>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>Incident ID</TableCell>
                      <TableCell>Type</TableCell>
                      <TableCell>Location</TableCell>
                      <TableCell>Severity</TableCell>
                      <TableCell>Status</TableCell>
                      <TableCell>Date & Time</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {incidents.map((incident) => (
                      <TableRow key={incident.id} hover>
                        <TableCell fontWeight={600}>{incident.incident_id}</TableCell>
                        <TableCell>
                          <Chip label={incident.incident_type} size="small" variant="outlined" />
                        </TableCell>
                        <TableCell sx={{ maxWidth: 200 }}>
                          <Typography variant="body2" noWrap>
                            {incident.location}
                          </Typography>
                        </TableCell>
                        <TableCell>
                          <Chip
                            label={incident.severity}
                            size="small"
                            color={severityColors[incident.severity]}
                          />
                        </TableCell>
                        <TableCell>
                          <Chip
                            label={incident.status}
                            size="small"
                            color={statusColors[incident.status]}
                          />
                        </TableCell>
                        <TableCell>
                          {new Date(incident.created_at).toLocaleString()}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
              <TablePagination
                component="div"
                count={incidents.length}
                page={page}
                onPageChange={(e, p) => setPage(p)}
                rowsPerPage={rowsPerPage}
                onRowsPerPageChange={(e) => {
                  setRowsPerPage(parseInt(e.target.value));
                  setPage(0);
                }}
              />
            </>
          ) : (
            <Typography textAlign="center" color="text.secondary" sx={{ py: 4 }}>
              No incident reports found.
            </Typography>
          )}
        </CardContent>
      </Card>
    </Box>
  );
};

export default AlertHistory;
